  (65, 'oma-jamu', 'why_its_here', (select count(*)::int from venues where slug = 'oma-jamu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '2b4b7ce1111a05a164cd1393852760c6'), md5('A budget vegan cafe and organic grocery near the Puseh temple in Batu Bolong. Plant-based Indonesian food runs all day, alongside cold-pressed juices, kombucha and traditional jamu tonics.') = 'ca3683b86d8b48bdf9ace629abbaa5db'),
