  (73, 'pak-gula', 'why_its_here', (select count(*)::int from venues where slug = 'pak-gula' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '18373a5a1514daa2986d75019c3b3845'), md5('PAK GULA is a two-storey restaurant in Bingin from the team behind The Cashew Tree. Sharing plates include char siu pork bao, vegetable dumplings, chicken satay and braised beef curry. Downstairs is casual; upstairs is a low-lit dinner room with communal tables and a bar.') = '80fbe64f037e3050c93b8377eb0b93db'),
