  (79, 'paradise-padel-bali', 'why_its_here', (select count(*)::int from venues where slug = 'paradise-padel-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '27cb42c09b0b0d1188d65ab15d251856'), md5('The padel club on Jalan Subak Sari rents equipment and has parking, a shop, a restaurant and changing rooms. Courts book through Playtomic, and a 60-minute session with a coach starts at 900,000 IDR. Tournaments and mixed-level sessions run regularly.') = 'c5332eb10dc9b781ad6e71d5ea2f280e'),
