  (86, 'pizzaria-hyatt', 'why_its_here', (select count(*)::int from venues where slug = 'pizzaria-hyatt' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c659ab6cbf573c5e31bfdc25dbc398ef'), md5('Pizzaria is Hyatt Regency Bali''s beachfront Italian restaurant and bar on Sanur Beach, with sea views. Antipasti, wood-fired sourdough pizza, pasta, seafood and meat are served at lunch and dinner daily. Sunday Brunch adds live grills and carvings.') = 'f4fc302f633f1439af6988572b735ff3'),
  (87, 'pizzaria-hyatt', 'best_for', (select count(*)::int from venues where slug = 'pizzaria-hyatt' and status = 'active' and publication_status = 'published' and md5(best_for) = '56ea168587899a40b9d608a7011fd547'), md5('An upscale beachfront dinner as a couple or for a special occasion, Sunday brunch with a group, or an early family meal') = '85efd6147aeb2c0640a1a0f14705a0e5'),
