  (92, 'prime-plaza-hotel-sanur-fitness-centre', 'why_its_here', (select count(*)::int from venues where slug = 'prime-plaza-hotel-sanur-fitness-centre' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3e67888da0afaaeaf4c1249d394689be'), md5('Prime Plaza Hotel Sanur''s gym is open to the public; hotel guests train free. Walk-ins pay 100,000 IDR at peak and 75,000 IDR off peak, which includes a locker, hot and cold showers and spa access. The gym has treadmills and stationary bikes alongside free weights and machines. Personal trainers can be booked ahead by the hour or by the day or week. The property also has a sauna and a hot tub, plus a 110-metre pool.') = '656ccb3dc7672a4b2436d0eecbfba79f'),
  (93, 'prime-plaza-hotel-sanur-fitness-centre', 'best_for', (select count(*)::int from venues where slug = 'prime-plaza-hotel-sanur-fitness-centre' and status = 'active' and publication_status = 'published' and md5(best_for) = '10fe987d1ac739b9cbb0961e8514bbca'), md5('A cheap walk-in workout in Sanur, with locker, shower and spa access in the entry price') = '4e336722c70cc5bffbb9796ddbb23c9d'),
  (94, 'pullman-bali-legian-beach-kuta-legian', 'why_its_here', (select count(*)::int from venues where slug = 'pullman-bali-legian-beach-kuta-legian' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5d7e4e04a42fa4555b428e58d3da1584'), md5('Pullman Bali Legian Beach has a resort spa for traditional massage; book on the hotel''s own website.') = 'fa84819341b35a2de2e2054ff4a5de62'),
  (95, 'pullman-bali-legian-beach-kuta-legian', 'best_for', (select count(*)::int from venues where slug = 'pullman-bali-legian-beach-kuta-legian' and status = 'active' and publication_status = 'published' and md5(best_for) = '9953afe9d562a858f93409bfdac700a3'), md5('Traditional massage at the Pullman in Legian') = 'f90ca074e9461f333c49576eff6eee42'),
  (96, 'reform-pilates-bingin', 'why_its_here', (select count(*)::int from venues where slug = 'reform-pilates-bingin' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3dcb2b6f1e91602ebfff3e53b552cf42'), md5('A reformer pilates studio in Bingin, opened in 2023 by Abbey. Classes include Booty & Core, Body Blast and deep stretch. Pre- and post-natal reformer classes run for the first and second trimesters. Booking is online.') = 'f2183e039af044896ea2734645a1790b'),
  (97, 'reform-uluwatu', 'why_its_here', (select count(*)::int from venues where slug = 'reform-uluwatu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'abb59c417c3462698139e01056886a51'), md5('Reform+ is the second Reform Pilates location, in Uluwatu, running reformer classes that you book online.') = '50fc857539cdaf5518e0854003a62857'),
