  (99, 'retro-kitchen-and-bar', 'best_for', (select count(*)::int from venues where slug = 'retro-kitchen-and-bar' and status = 'active' and publication_status = 'published' and md5(best_for) = '198549a775f274e31b41645f00ee3b5e'), md5('Families with kids, or a group that wants Western and Indonesian options in one place') = '9cf5c0fa83e8053bb3303701cc32a252'),
  (100, 'rip-curl-school-of-surf', 'why_its_here', (select count(*)::int from venues where slug = 'rip-curl-school-of-surf' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '104968d2865a33561a857f3be4073be1'), md5('Rip Curl''s surf school is on Sanur beach inside the Prama Sanur Beach hotel and has run since 1998. It also teaches kitesurfing, stand-up paddle, windsurfing, wakeboarding, diving and foiling, with certification and rentals. The Little Ripper programme is for under-13s.') = '3a81986c4c81163bd1dc27c75af424d1'),
  (101, 'rockfish-cliffside', 'why_its_here', (select count(*)::int from venues where slug = 'rockfish-cliffside' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9abbe968cdb1d444fa0f9665abfe1195'), md5('Rockfish Cliffside is a restaurant on the cliffs in Pecatu, with a menu led by seafood and wagyu.') = 'c6b45d80123e0c62cd8c3cc7014eaca3'),
